export fn zblock_substring_search(a:?[*]const i64,length:usize)i64{if(a==null or length<3)return -1;const v=a.?[0..length];if(v[0]<0 or v[0]>256 or v[1]<1 or v[1]>64 or length!=@as(usize,@intCast(v[0]+v[1]+2)))return -1;for(v[2..])|x|{if(x<0 or x>127 or x==36)return -1;}const tn:usize=@intCast(v[0]);const pn:usize=@intCast(v[1]);const n=tn+pn+1;var s=[_]i64{0}**321;var z=[_]usize{0}**321;for(0..pn)|i|s[i]=v[2+tn+i];s[pn]=-1;for(0..tn)|i|s[pn+1+i]=v[2+i];var l:usize=0;var r:usize=0;for(1..n)|i|{z[i]=if(i<=r)@min(r-i+1,z[i-l])else 0;while(i+z[i]<n and s[z[i]]==s[i+z[i]]) : (z[i]+=1){}if(i+z[i]>0 and i+z[i]-1>r){l=i;r=i+z[i]-1;}}var found:i64=0;for(pn+1..n)|i|{if(z[i]>=pn)found+=1;}return found;}
